import{_ as a,a0 as i,w as p,s as T,ao as s,I as d,x as o,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"漫游 HTTP/2 | LCTT x X-CMD","titleTemplate":false,"description":"漫游 HTTP/2 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"漫游 HTTP/2 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"漫游 HTTP/2 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160813 Journey-to-HTTP2","title":"漫游 HTTP/2","tag":"201609","desc":""},"relativePath":"201609/20160813 Journey-to-HTTP2.md","filePath":"[post].md"}'),r={name:"201609/20160813 Journey-to-HTTP2.md"};function c(P,e,h,H,u,g){const t=i("Link");return p(),T("div",null,[e[45]||(e[45]=s(`<h1 id="漫游-http-2" tabindex="-1">漫游 HTTP/2 <a class="header-anchor" href="#漫游-http-2" aria-label="Permalink to “漫游 HTTP/2”">​</a></h1><p>自从我写了上一篇博文之后，就再也找不到空闲时间写文章了。今天我终于可以抽出时间写一些关于 HTTP 的东西。</p><p>我认为每一个 web 开发者都应该对这个支撑了整个 Web 世界的 HTTP 协议有所了解，这样才能帮助你更好的完成开发任务。</p><p>在这篇文章中，我将讨论什么是 HTTP，它是怎么产生的，它的地位，以及我们应该怎么使用它。</p><h3 id="http-是什么" tabindex="-1">HTTP 是什么 <a class="header-anchor" href="#http-是什么" aria-label="Permalink to “HTTP 是什么”">​</a></h3><p>首先我们要明白 HTTP 是什么。HTTP 是一个基于 <code>TCP/IP</code> 的应用层通信协议，它是客户端和服务端在互联网互相通讯的标准。它定义了内容是如何通过互联网进行请求和传输的。HTTP 是在应用层中抽象出的一个标准，使得主机（客户端和服务端）之间的通信得以通过 <code>TCP/IP</code> 来进行请求和响应。TCP 默认使用的端口是 <code>80</code>，当然也可以使用其它端口，比如 HTTPS 使用的就是 <code>443</code> 端口。</p><h3 id="http-0-9-单行协议-1991" tabindex="-1"><code>HTTP/0.9</code> - 单行协议 (1991) <a class="header-anchor" href="#http-0-9-单行协议-1991" aria-label="Permalink to “HTTP/0.9 - 单行协议 (1991)”">​</a></h3><p>HTTP 最早的规范可以追溯到 1991 年，那时候的版本是 <code>HTTP/0.9</code>，该版本极其简单，只有一个叫做 <code>GET</code> 的 请求方式。如果客户端要访问服务端上的一个页面，只需要如下非常简单的请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /index.html</span></span></code></pre></div><p>服务端的响应类似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(response body)</span></span>
<span class="line"><span>(connection closed)</span></span></code></pre></div><p>就这么简单，服务端捕获到请求后立马返回 HTML 并且关闭连接，在这之中：</p><ul><li>没有头信息（headers）</li><li>仅支持 <code>GET</code> 这一种请求方法</li><li>必须返回 HTML</li></ul><p>如同你所看到的，当时的 HTTP 协议只是一块基础的垫脚石。</p><h3 id="http-1-0-1996" tabindex="-1">HTTP/1.0 - 1996 <a class="header-anchor" href="#http-1-0-1996" aria-label="Permalink to “HTTP/1.0 - 1996”">​</a></h3><p>在 1996 年，新版本的 HTTP 对比之前的版本有了极大的改进，同时也被命名为 <code>HTTP/1.0</code>。</p><p>与 <code>HTTP/0.9</code> 只能返回 HTML 不同的是，<code>HTTP/1.0</code> 支持处理多种返回的格式，比如图片、视频、文本或者其他格式的文件。它还增加了更多的请求方法（如 <code>POST</code> 和 <code>HEAD</code>），请求和响应的格式也相应做了改变，两者都增加了头信息；引入了状态码来定义返回的特征；引入了字符集支持；支持多段类型（multi-part）、用户验证信息、缓存、内容编码格式等等。</p><p>一个简单的 HTTP/1.0 请求大概是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.0</span></span>
<span class="line"><span>Host: kamranahmed.info</span></span>
<span class="line"><span>User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_10_5)</span></span>
<span class="line"><span>Accept: */*</span></span></code></pre></div><p>正如你所看到的，在请求中附带了客户端中的一些个人信息、响应类型要求等内容。这些是在 <code>HTTP/0.9</code> 无法实现的，因为那时候没有头信息。</p><p>一个对上述请求的响应例子如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.0 200 OK</span></span>
<span class="line"><span>Content-Type: text/plain</span></span>
<span class="line"><span>Content-Length: 137582</span></span>
<span class="line"><span>Expires: Thu, 05 Dec 1997 16:00:00 GMT</span></span>
<span class="line"><span>Last-Modified: Wed, 5 August 1996 15:55:28 GMT</span></span>
<span class="line"><span>Server: Apache 0.84</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(response body)</span></span>
<span class="line"><span>(connection closed)</span></span></code></pre></div><p>从 <code>HTTP/1.0</code> （HTTP 后面跟的是版本号）早期开始，在状态码 <code>200</code> 之后就附带一个原因短语（你可以用来描述状态码）。</p><p>在这个较新一点的版本中，请求和响应的头信息仍然必须是 <code>ASCII</code> 编码，但是响应的内容可以是任意类型，如图片、视频、HTML、文本或其他类型，服务器可以返回任意内容给客户端。所以这之后，<code>HTTP</code> 中的“超文本（Hyper Text）”成了名不副实。 <code>HMTP</code> （超媒体传输协议 - Hypermedia transfer protocol）可能会更有意义，但是我猜我们还是会一直沿用这个名字。</p><p><code>HTTP/1.0</code> 的一个主要缺点就是它不能在一个连接内拥有多个请求。这意味着，当客户端需要从服务器获取东西时，必须建立一个新的 TCP 连接，并且处理完单个请求后连接即被关闭。需要下一个东西时，你必须重新建立一个新的连接。这样的坏处在哪呢？假设你要访问一个有 <code>10</code> 张图片，<code>5</code> 个样式表（stylesheet）和 <code>5</code> 个 JavaScript 的总计 <code>20</code> 个文件才能完整展示的一个页面。由于一个连接在处理完成一次请求后即被关闭，所以将有 <code>20</code> 个单独的连接，每一个文件都将通过各自对应的连接单独处理。当连接数量变得庞大的时候就会面临严重的性能问题，因为 <code>TCP</code> 启动需要经过三次握手，才能缓慢开始。</p><h4 id="三次握手" tabindex="-1">三次握手 <a class="header-anchor" href="#三次握手" aria-label="Permalink to “三次握手”">​</a></h4><p>三次握手是一个简单的模型，所有的 <code>TCP</code> 连接在传输应用数据之前都需要在三次握手中传输一系列数据包。</p><ul><li><code>SYN</code> - 客户端选取一个随机数，我们称为 <code>x</code>，然后发送给服务器。</li><li><code>SYN ACK</code> - 服务器响应对应请求的 <code>ACK</code> 包中，包含了一个由服务器随机产生的数字，我们称为 <code>y</code>，并且把客户端发送的 <code>x+1</code>，一并返回给客户端。</li><li><code>ACK</code> - 客户端在从服务器接受到 <code>y</code> 之后把 <code>y</code> 加上 <code>1</code> 作为一个 <code>ACK</code> 包返回给服务器。</li></ul><p>一旦三次握手完成后，客户端和服务器之间就可以开始交换数据。值得注意的是，当客户端发出最后一个 <code>ACK</code> 数据包后，就可以立刻向服务器发送应用数据包，而服务器则需要等到收到这个 <code>ACK</code> 数据包后才能接受应用数据包。</p><p><img src="http://i.imgur.com/uERG2G2.png" alt=""></p><blockquote><p>请注意，上图有点小问题，客户端发回的最后一个 ACK 包仅包含 <code>y+1</code>，上图应该是 <code>ACK:y+1</code> 而不是 <code>ACK:x+1,y+1</code></p></blockquote><p>然而，某些 HTTP/1.0 的实现试图通过新引入一个称为 <code>Connection: keep-alive</code> 的头信息来克服这一问题，这个头信息意味着告诉服务器“嘿，服务器，请不要关闭此连接，我还要用它”。但是，这并没有得到广泛的支持，问题依然存在。</p><p>除了无连接之外，HTTP 还是一个无状态的协议，即服务器不维护有关客户端的信息。因此每个请求必须给服务器必要的信息才能完成请求，每个请求都与之前的旧的请求无关。所以，这增加了推波助澜的作用，客户端除了需要新建大量连接之外，在每次连接中还需要发送许多重复的数据，这导致了带宽的大量浪费。</p><h3 id="http-1-1-1999" tabindex="-1"><code>HTTP/1.1</code> - 1999 <a class="header-anchor" href="#http-1-1-1999" aria-label="Permalink to “HTTP/1.1 - 1999”">​</a></h3><p><code>HTTP/1.0</code> 经过仅仅 3 年，下一个版本，即 <code>HTTP/1.1</code> 就在 1999 年发布了，改进了它的前身很多问题，主要的改进包括：</p><ul><li><strong>增加了许多 HTTP 请求方法</strong>，包括 <code>PUT</code>、<code>PATCH</code>、<code>HEAD</code>、<code>OPTIONS</code>、<code>DELETE</code>。</li><li><strong>主机标识符</strong> <code>Host</code> 在 <code>HTTP/1.0</code> 并不是必须的，而在 <code>HTTP/1.1</code> 是必须的。</li><li>如上所述的<strong>持久连接</strong>。在 <code>HTTP/1.0</code> 中每个连接只有一个请求并在该请求结束后被立即关闭，这导致了性能问题和增加了延迟。 <code>HTTP/1.1</code> 引入了持久连接，即连接在默认情况下是不关闭并保持开放的，这允许多个连续的请求使用这个连接。要关闭该连接只需要在头信息加入 <code>Connection: close</code>，客户通常在最后一个请求里发送这个头信息就能安全地关闭连接。</li><li>新版本还引入了“<strong>管线化（pipelining）</strong>”的支持，客户端可以不用等待服务器返回响应，就能在同一个连接内发送多个请求给服务器，而服务器必须以接收到的请求相同的序列发送响应。但是你可能会问了，客户端如何知道哪里是第一个响应下载完成而下一个响应内容开始的地方呢？要解决这个问题，头信息必须有 <code>Content-Length</code>，客户可以使用它来确定哪些响应结束之后可以开始等待下一个响应。 <ul><li>值得注意的是，为了从持久连接或管线化中受益， 头部信息必须包含 <code>Content-Length</code>，因为这会使客户端知道什么时候完成了传输，然后它可以发送下一个请求（持久连接中，以正常的依次顺序发送请求）或开始等待下一个响应（启用管线化时）。</li><li>但是，使用这种方法仍然有一个问题。那就是，如果数据是动态的，服务器无法提前知道内容长度呢？那么在这种情况下，你就不能使用这种方法中获益了吗？为了解决这个问题，<code>HTTP/1.1</code> 引进了分块编码。在这种情况下，服务器可能会忽略 <code>Content-Length</code> 来支持分块编码（更常见一些）。但是，如果它们都不可用，那么连接必须在请求结束时关闭。</li></ul></li><li>在动态内容的情况下<strong>分块传输</strong>，当服务器在传输开始但无法得到 <code>Content-Length</code> 时，它可能会开始按块发送内容（一块接一块），并在传输时为每一个小块添加 <code>Content-Length</code>。当发送完所有的数据块后，即整个传输已经完成后，它发送一个空的小块，比如设置 <code>Content-Length</code> 为 0 ，以便客户端知道传输已完成。为了通知客户端块传输的信息，服务器在头信息中包含了 <code>Transfer-Encoding: chunked</code>。</li><li>不像 HTTP/1.0 中只有 Basic 身份验证方式，<code>HTTP/1.1</code> 包括摘要验证方式（digest authentication）和代理验证方式（proxy authentication）。</li><li>缓存。</li><li>范围请求（Byte Ranges）。</li><li>字符集。</li><li>内容协商（Content Negotiation）。</li><li>客户端 cookies。</li><li>支持压缩。</li><li>新的状态码。</li><li>等等。</li></ul>`,36)),d("p",null,[e[2]||(e[2]=o("我不打算在这里讨论所有 ",-1)),e[3]||(e[3]=d("code",null,"HTTP/1.1",-1)),e[4]||(e[4]=o(" 的特性，因为你可以围绕这个话题找到很多关于这些的讨论。我建议你阅读 ",-1)),n(t,{href:"http://www.ra.ethz.ch/cdstore/www8/data/2136/pdf/pd1.pdf"},{default:l(()=>[...e[0]||(e[0]=[d("code",null,"HTTP/1.0",-1),o(" 和 ",-1),d("code",null,"HTTP/1.1",-1),o(" 版本之间的主要差异",-1)])]),_:1}),e[5]||(e[5]=o("，希望了解更多可以读",-1)),n(t,{href:"https://tools.ietf.org/html/rfc2616"},{default:l(()=>[...e[1]||(e[1]=[o("原始的 RFC",-1)])]),_:1}),e[6]||(e[6]=o("。",-1))]),d("p",null,[e[8]||(e[8]=d("code",null,"HTTP/1.1",-1)),e[9]||(e[9]=o(" 在 1999 年推出，到现在已经是多年前的标准。虽然，它比前一代改善了很多，但是网络日新月异，它已经垂垂老矣。相比之前，加载网页更是一个资源密集型任务，打开一个简单的网页已经需要建立超过 30 个连接。你或许会说，",-1)),e[10]||(e[10]=d("code",null,"HTTP/1.1",-1)),e[11]||(e[11]=o(" 具有持久连接，为什么还有这么多连接呢？其原因是，在任何时刻 ",-1)),e[12]||(e[12]=d("code",null,"HTTP/1.1",-1)),e[13]||(e[13]=o(" 只能有一个未完成的连接。 ",-1)),e[14]||(e[14]=d("code",null,"HTTP/1.1",-1)),e[15]||(e[15]=o(" 试图通过引入管线来解决这个问题，但它并没有完全地解决。因为一旦管线遇到了缓慢的请求或庞大的请求，后面的请求便被阻塞住，它们必须等待上一个请求完成。为了克服 ",-1)),e[16]||(e[16]=d("code",null,"HTTP/1.1",-1)),e[17]||(e[17]=o(" 的这些缺点，开发人员开始实现一些解决方法，例如使用 spritesheets、在 CSS 中编码图像、单个巨型 CSS / JavaScript 文件、",-1)),n(t,{href:"https://www.maxcdn.com/one/visual-glossary/domain-sharding-2/"},{default:l(()=>[...e[7]||(e[7]=[o("域名切分",-1)])]),_:1}),e[18]||(e[18]=o("等。",-1))]),e[46]||(e[46]=s('<h3 id="spdy-2009" tabindex="-1">SPDY - 2009 <a class="header-anchor" href="#spdy-2009" aria-label="Permalink to “SPDY - 2009”">​</a></h3><p>谷歌走在业界前列，为了使网络速度更快，提高网络安全，同时减少网页的等待时间，他们开始实验替代的协议。在 2009 年，他们宣布了 <code>SPDY</code>。</p><blockquote><p><code>SPDY</code> 是谷歌的商标，而不是一个缩写。</p></blockquote><p>显而易见的是，如果我们继续增加带宽，网络性能开始的时候能够得到提升，但是到了某个阶段后带来的性能提升就很有限了。但是如果把这些优化放在等待时间上，比如减少等待时间，将会有持续的性能提升。这就是 <code>SPDY</code> 优化之前的协议的核心思想，减少等待时间来提升网络性能。</p><blockquote><p>对于那些不知道其中区别的人，等待时间就是延迟，即数据从源到达目的地需要多长时间（单位为毫秒），而带宽是每秒钟数据的传输量（比特每秒）。</p></blockquote><p><code>SPDY</code> 的特点包括：复用、压缩、优先级、安全性等。我不打算展开 <code>SPDY</code> 的细节。在下一章节，当我们将介绍 <code>HTTP/2</code>，这些都会被提到，因为 <code>HTTP/2</code> 大多特性是从 <code>SPDY</code> 受启发的。</p><p><code>SPDY</code> 没有试图取代 HTTP，它是处于应用层的 HTTP 之上的一个传输层，它只是在请求被发送之前做了一些修改。它开始成为事实标准，大多数浏览器都开始支持了。</p><p>2015年，谷歌不想有两个相互竞争的标准，所以他们决定将其合并到 HTTP 协议，这样就导致了 <code>HTTP/2</code> 的出现和 <code>SPDY</code> 的废弃。</p><h3 id="http-2-2015" tabindex="-1"><code>HTTP/2</code> - 2015 <a class="header-anchor" href="#http-2-2015" aria-label="Permalink to “HTTP/2 - 2015”">​</a></h3><p>现在想必你明白了为什么我们需要另一个版本的 HTTP 协议了。 <code>HTTP/2</code> 是专为了低延迟地内容传输而设计。主要特点和与 <code>HTTP/1.1</code> 的差异包括：</p><ul><li>使用二进制替代明文</li><li>多路传输 - 多个异步 HTTP 请求可以使用单一连接</li><li>报头使用 HPACK 压缩</li><li>服务器推送 - 单个请求多个响应</li><li>请求优先级</li><li>安全性</li></ul><p><img src="http://i.imgur.com/S85j8gg.png" alt=""></p><h4 id="_1-二进制协议" tabindex="-1">1. 二进制协议 <a class="header-anchor" href="#_1-二进制协议" aria-label="Permalink to “1. 二进制协议”">​</a></h4><p><code>HTTP/2</code> 通过使其成为一个二进制协议以解决 HTTP/1.x 中存在的延迟问题。作为一个二进制协议，它更容易解析，但可读性却不如 <code>HTTP/1.x</code>。帧（frames）和流（stream）的概念组成了 <code>HTTP/2</code> 的主要部分。</p><p><strong>帧和流</strong></p>',15)),d("p",null,[e[20]||(e[20]=s("现在 HTTP 消息是由一个或多个帧组成的。<code>HEADERS</code> 帧承载了元数据（meta data），<code>DATA</code> 帧则承载了内容。还有其他类型的帧（<code>HEADERS</code>、<code>DATA</code>、<code>RST_STREAM</code>、<code>SETTINGS</code>、<code>PRIORITY</code> 等等），这些你可以通过",15)),n(t,{href:"https://http2.github.io/http2-spec/#FrameTypes"},{default:l(()=>[...e[19]||(e[19]=[o("HTTP/2 规范",-1)])]),_:1}),e[21]||(e[21]=o("来了解。",-1))]),e[47]||(e[47]=s('<p>每个 <code>HTTP/2</code> 请求和响应都被赋予一个唯一的流 ID，并切分成帧。帧就是一小片二进制数据。帧的集合称为流，每个帧都有个标识了其所属流的流 ID，所以在同一个流下的每个帧具有共同的报头。值得注意的是，​除了流 ID 是唯一的之外，​由客户端发起的请求使用了奇数作为流 ID，从来自服务器的响应使用了偶数作为流 ID。</p><p>除了 <code>HEADERS</code> 帧和 <code>DATA</code> 帧，另一个值得一提的帧是 <code>RST_STREAM</code>。这是一个特殊的帧类型，用来中止流，即客户可以发送此帧让服务器知道，我不再需要这个流了。在 <code>HTTP/1.1</code> 中让服务器停止给客户端发送响应的唯一方法是关闭连接，这样造成了延迟增加，因为之后要发送请求时，就要必须打开一个新的请求。而在 <code>HTTP/2</code> ，客户端可以使用 <code>RST_STREAM</code> 来停止接收特定的数据流，而连接仍然打开着，可以被其他请求使用。</p><h4 id="_2-多路传输" tabindex="-1">2. 多路传输 <a class="header-anchor" href="#_2-多路传输" aria-label="Permalink to “2. 多路传输”">​</a></h4><p>因为 <code>HTTP/2</code> 是一个二进制协议，而且如上所述它使用帧和流来传输请求与响应，一旦建立了 TCP 连接，相同连接内的所有流都可以同过这个 TCP 连接异步发送，而不用另外打开连接。反过来说，服务器也可以使用同样的异步方式返回响应，也就是说这些响应可以是无序的，客户端使用分配的流 ID 来识别数据包所属的流。这也解决了 HTTP/1.x 中请求管道被阻塞的问题，即客户端不必等待占用时间的请求而其他请求仍然可以被处理。</p><h4 id="_3-hpack-请求头部压缩" tabindex="-1">3. HPACK 请求头部压缩 <a class="header-anchor" href="#_3-hpack-请求头部压缩" aria-label="Permalink to “3. HPACK 请求头部压缩”">​</a></h4><p>RFC 花了一篇文档的篇幅来介绍针对发送的头信息的优化，它的本质是当我们在同一客户端上不断地访问服务器时，许多冗余数据在头部中被反复发送，有时候仅仅是 cookies 就能增加头信息的大小，这会占用许多宽带和增加传输延迟。为了解决这个问题，<code>HTTP/2</code> 引入了头信息压缩。</p><p><img src="http://i.imgur.com/3IPWXvR.png" alt=""></p><p>不像请求和响应那样，头信息中的信息不会以 <code>gzip</code> 或者 <code>compress</code> 等格式压缩。而是采用一种不同的机制来压缩头信息，客户端和服务器同时维护一张头信息表，储存了使用了哈夫曼编码进行编码后的头信息的值，并且后续请求中若出现同样的字段则忽略重复值（例如用户代理（user agent）等），只发送存在两边信息表中它的引用即可。</p><p>我们说的头信息，它们同 HTTP/1.1 中一样，并在此基础上增加了一些伪头信息，如 <code>:scheme</code>，<code>:host</code> 和 <code>:path</code>。</p><h4 id="_4-服务器推送" tabindex="-1">4. 服务器推送 <a class="header-anchor" href="#_4-服务器推送" aria-label="Permalink to “4. 服务器推送”">​</a></h4><p>服务器推送是 <code>HTTP/2</code> 的另一个巨大的特点。对于服务器来说，当它知道客户端需要一定的资源后，它可以把数据推送到客户端，即使客户端没有请求它。例如，假设一个浏览器在加载一个网页时，它解析了整个页面，发现有一些内容必须要从服务端获取，然后发送相应的请求到服务器以获取这些内容。</p><p>服务器推送减少了传输这些数据需要来回请求的次数。它是如何做到的呢？服务器通过发送一个名字为 <code>PUSH_PROMISE</code> 特殊的帧通知到客户端“嘿，我准备要发送这个资源给你了，不要再问我要了。”这个 <code>PUSH_PROMISE</code> 帧与要产生推送的流联系在一起，并包含了要推送的流 ID，也就是说这个流将会被服务器推送到客户端上。</p><h4 id="_5-请求优先级" tabindex="-1">5. 请求优先级 <a class="header-anchor" href="#_5-请求优先级" aria-label="Permalink to “5. 请求优先级”">​</a></h4><p>当流被打开的时候，客户端可以在 <code>HEADERS</code> 帧中包含优先级信息来为流指定优先级。在任何时候，客户端都可以发送 <code>PRIORITY</code> 帧来改变流的优先级。</p><p>如果没有任何优先级信息，服务器将异步地无序地处理这些请求。如果流分配了优先级，服务器将基于这个优先级来决定需要分配多少资源来处理这个请求。</p><h4 id="_6-安全性" tabindex="-1">6. 安全性 <a class="header-anchor" href="#_6-安全性" aria-label="Permalink to “6. 安全性”">​</a></h4><p>在是否强制使用 <code>TLS</code> 来增加安全性的问题上产生了大范围的讨论，讨论的结果是不强制使用。然而大多数厂商只有在使用 <code>TLS</code> 时才能使用 <code>HTTP/2</code>。所以 <code>HTTP/2</code> 虽然规范上不要求加密，但是加密已经约定俗成了。这样，在 <code>TLS</code> 之上实现 <code>HTTP/2</code> 就有了一些强制要求，比如，<code>TLS</code> 的最低版本为 <code>1.2</code>，必须达到某种级别的最低限度的密钥大小，需要布署 ephemeral 密钥等等。</p>',17)),d("p",null,[e[23]||(e[23]=o("到现在 ",-1)),e[24]||(e[24]=d("code",null,"HTTP/2",-1)),e[25]||(e[25]=o(" 已经",-1)),n(t,{href:"http://caniuse.com/#search=http2"},{default:l(()=>[...e[22]||(e[22]=[o("完全超越了 SPDY",-1)])]),_:1}),e[26]||(e[26]=o("，并且还在不断成长，HTTP/2 有很多关系性能的提升，我们应该开始布署它了。",-1))]),d("p",null,[e[29]||(e[29]=o("如果你想更深入的了解细节，请访问",-1)),n(t,{href:"https://http2.github.io/http2-spec"},{default:l(()=>[...e[27]||(e[27]=[o("该规范的链接",-1)])]),_:1}),e[30]||(e[30]=o("和",-1)),n(t,{href:"http://www.http2demo.io/"},{default:l(()=>[...e[28]||(e[28]=[o(" HTTP/2 性能提升演示的链接",-1)])]),_:1}),e[31]||(e[31]=o("。请在留言板写下你的疑问或者评论，最后如果你发现有错误，请同样留言指出。",-1))]),e[48]||(e[48]=d("p",null,"这就是全部了，我们之后再见~",-1)),e[49]||(e[49]=d("hr",null,null,-1)),d("p",null,[e[33]||(e[33]=o("via: ",-1)),n(t,{href:"http://kamranahmed.info/blog/2016/08/13/http-in-depth/"},{default:l(()=>[...e[32]||(e[32]=[o("http://kamranahmed.info/blog/2016/08/13/http-in-depth/",-1)])]),_:1})]),d("p",null,[e[37]||(e[37]=o("作者：",-1)),n(t,{href:"http://github.com/kamranahmedse"},{default:l(()=>[...e[34]||(e[34]=[o("Kamran Ahmed",-1)])]),_:1}),e[38]||(e[38]=o(" 译者：",-1)),n(t,{href:"https://github.com/NearTan"},{default:l(()=>[...e[35]||(e[35]=[o("NearTan",-1)])]),_:1}),e[39]||(e[39]=o(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[36]||(e[36]=[o("wxy",-1)])]),_:1})]),d("p",null,[e[42]||(e[42]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[40]||(e[40]=[o("LCTT",-1)])]),_:1}),e[43]||(e[43]=o(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...e[41]||(e[41]=[o("Linux中国",-1)])]),_:1}),e[44]||(e[44]=o(" 荣誉推出",-1))])])}const k=a(r,[["render",c]]);export{f as __pageData,k as default};
